svg.script:
{
  "metadata": {
    "title": "Azure Architecture",
    "projectName": "Food Delivery System",
    "description": "Cloud infrastructure on Microsoft Azure",
    "version": "1.0",
    "created": "2024-01-01T00:00:00Z",
    "mode": "light"
  },
  "config": {
    "layout": {
      "canvasWidth": 1920,
      "canvasHeight": 1080,
      "resourceGroupX": 300,
      "resourceGroupY": 220,
      "resourceGroupWidth": 1200,
      "resourceGroupHeight": 720
    },
    "styling": {
      "mode": "light",
      "canvasColor": "#FFFFFF",
      "fillColor": "#E5E5E5",
      "strokeColor": "#1A1A1A",
      "cornerRadius": 8,
      "strokeWidth": 1.5
    }
  },
  "data": {
    "resourceGroups": [{"id": "rg1", "name": "Resource Group", "x": 300, "y": 220, "width": 1200, "height": 720}],
    "services": [
      {"id": "compute", "name": "Compute", "description": "Virtual Machines, App Service", "x": 420, "y": 360, "width": 220, "height": 120},
      {"id": "storage", "name": "Storage", "description": "Blob Storage, File Share", "x": 760, "y": 360, "width": 220, "height": 120},
      {"id": "database", "name": "Database", "description": "SQL Database, Cosmos DB", "x": 1100, "y": 360, "width": 220, "height": 120}
    ],
    "relationships": [
      {"from": "compute", "to": "storage", "label": "accesses"},
      {"from": "compute", "to": "database", "label": "queries"}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#azure-architecture-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Azure Architecture Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Azure Architecture] Invalid JSON:', e.message);
  }
})();
